-- ----------------------------
-- Table structure for iheritages
-- ----------------------------
DROP TABLE IF EXISTS `iheritages`;
CREATE TABLE `iheritages` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '传承项目ID',
  `heritage_name` char(30) DEFAULT NULL COMMENT '传承项目名称',
  `heritage_region` char(10) DEFAULT NULL COMMENT '传承项目地区',
  `heritage_user` char(20) DEFAULT NULL COMMENT '发表人',
  `heritage_date` char(16) DEFAULT NULL COMMENT '发表日期',
  `heritage_content` varchar(4000) DEFAULT NULL COMMENT '传承项目介绍',
  `heritage_image` varchar(300) DEFAULT NULL COMMENT '传承项目配图存放路径',
  `heritage_video` varchar(200) DEFAULT NULL COMMENT '传承项目视频存放路径',
  `heritage_grade` char(10) DEFAULT NULL COMMENT '非遗等级（如国家级、省级等）',
  `heritage_classes` char(30) DEFAULT NULL COMMENT '项目类别',
  `heritage_group` char(10) DEFAULT NULL COMMENT '项目批次',
  `Inheritor_name` char(16) DEFAULT NULL COMMENT '传承人',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=66 DEFAULT CHARSET=utf8;

