INSERT INTO `news` VALUES ('20', '韶关市非遗进校园系列活动——韶关市中等职业技术学院', '如光不息', '2021-04-23', '<p>	<span style=\"color: rgb(42, 51, 60);\">为提高广大师生群体非物质文化遗产保护传承意识，推动本土传统文化在校园普及和传承，为韶关作为广东省“非遗”进校园主会场做好提前预热和谋划，2019年11月-12月韶关市文化馆、韶关市非物质文化遗产保护中心举办了韶关市“非遗进校园”系列活动。</span></p><p>	<span style=\"color: rgb(42, 51, 60);\">本次组织了6个传统技艺类项目走进韶关市中等职业技术学院校园，五场活动均得到了校方大力支持，能专门指派教务处主任对接所有工作细节，全程组织学生积极参与，使活动有序开展，取得了一定成效，有成品，有照片、有视频，有分享。&nbsp;</span></p><p><img src=\"http://localhost:3001/Editor/20210423/1619185782130.jpg\" style=\"display: block; margin: auto;\"></p><p><img src=\"http://localhost:3001/Editor/20210423/1619185794603.jpg\" style=\"display: block; margin: auto;\"></p><p><br></p><p class=\"ql-align-center\"><img src=\"http://localhost:3001/Editor/20210423/1619185812377.jpg\"></p><p><span style=\"background-color: white; color: rgb(42, 51, 60);\">参与的学生能积极分享在参与互动过程中的感想和思考，使活动能够真正落地，深入人心并通过表达让广大师生有一个思想上的认同感。</span></p>');
