INSERT INTO `news` VALUES ('24', '“非遗保护·同行童乐”韶关市非遗体验游活动顺利举办！', '如光不息', '2021-04-23', '<p class=\"ql-align-justify\">	<span style=\"color: rgb(42, 51, 60);\">韶关历史文化底蕴深厚，拥有丰富的文化遗产资源，为了推动文旅融合，促进非遗+旅游发展，韶关市文化馆、韶关市非遗保护中心组织我市50名中小学生于6月8日成功举办了“非遗保护·同行童乐”韶关市非遗体验游活动。</span></p><p class=\"ql-align-justify\">	<span style=\"color: rgb(42, 51, 60);\">本次系列活动围绕弘扬优秀传统文化，深入非遗工作站、非遗项目传承基地。由我中心非遗专干普及非遗相关知识，代表性传承人讲解非遗项目百年的起源，发展，现状以及技艺特征，使得非遗项目更接地气，更贴近生活，真正的“活”起来。</span></p><p><img src=\"http://localhost:3001/Editor/20210423/1619186217995.jpg\"></p><p><br></p><p><img src=\"http://localhost:3001/Editor/20210423/1619186228062.jpg\"></p><p><br></p><p><img src=\"http://localhost:3001/Editor/20210423/1619186238312.jpg\"></p><p><br></p><p><img src=\"http://localhost:3001/Editor/20210423/1619186245108.jpg\"></p><p><br></p><p><br></p>');

-- ----------------------------
-- Table structure for notice
-- ----------------------------
DROP TABLE IF EXISTS `notice`;
CREATE TABLE `notice` (
  `notice_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '公告ID',
  `content` varchar(150) DEFAULT NULL COMMENT '公告内容',
  `date` char(32) DEFAULT NULL COMMENT '发布日期',
  `status` char(6) DEFAULT NULL COMMENT '展示状态',
  `author` char(30) DEFAULT NULL COMMENT '发布者',
  PRIMARY KEY (`notice_id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8;

