-- ----------------------------
-- Table structure for posts
-- ----------------------------
DROP TABLE IF EXISTS `posts`;
CREATE TABLE `posts` (
  `post_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '贴子ID',
  `title` char(30) DEFAULT NULL COMMENT '贴子标题',
  `date` char(32) DEFAULT NULL COMMENT '发帖日期',
  `content` varchar(3000) DEFAULT NULL COMMENT '帖子内容',
  `author` char(20) DEFAULT NULL COMMENT '发帖人',
  `status` char(6) DEFAULT NULL COMMENT '展示状态',
  `grade` char(6) DEFAULT NULL COMMENT '展示等级',
  `views` int(5) DEFAULT NULL COMMENT '贴子被浏览次数',
  PRIMARY KEY (`post_id`)
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of posts
-- ----------------------------
INSERT INTO `posts` VALUES ('19', '带您走进“织中之圣”—缂丝', '2021-04-13', '<p>缂(kè，同:刻)丝，又称\"刻丝\"，是中国传统丝绸艺术品中的精华。是中国丝织业中最传统的一种挑经显纬，极具欣赏装饰性丝织品。</p><p><br></p><p>宋元以来一直是皇家御用织物之一，常用以织造帝后服饰、御真(御容像)和摹缂名人书画。因织造过程极其细致，摹缂常胜于原作，而存世精品又极为稀少，是当今织绣收藏、拍卖的亮点。常有\"一寸缂丝一寸金\"和\"织中之圣\"的盛名。（苏州缂丝画也与杭州丝织画、永春纸织画、四川竹帘画并称为中国的\"四大家织\"。）</p><p><br></p><p>2006年5月，苏州缂丝织造技艺入选第一批国家级非物质文化遗产名录;2009年9月，缂丝又作为中国蚕桑丝织技艺入选世界非物质文化遗产。</p>', '如光不息', '显示', '普通', '8');
INSERT INTO `posts` VALUES ('20', '非遗的“大众评委”不可忽视', '2021-04-13', '<p>目前，一些综艺选秀类节目中不光设有专家评委，还有大众评委，为的是不光从专业角度去评判选手的艺术造诣，更提供大众审美的参考。非遗的活态传承同样离不开“大众评委”的打分，这位“大众评委”就包括市场。在一定程度上，市场不光会考量艺术价值，民众的需求和对非遗产品的了解程度，更是推动了非遗项目增强自身“造血”功能，从而更好地贴近生活、融入生活，在新时代焕发新的光彩。</p><p><br></p><p>传统工艺、技术本身就是人们衣食住行的一部分，承载着生活的智慧、地域的特点以及情感的寄托，“活”在人们的生活中才得以流传至今。让非遗继续“活”在生活中、更具生命力是一个时代课题。可喜的是，有关部门和非遗传承人等业界人士按照创造性转化、创新性发展的思路，对更好地传承发展非遗积极实践、勇于尝试。</p>', '如光不息', '显示', '普通', '1');
INSERT INTO `posts` VALUES ('22', '为非遗保护工作开辟新路径', '2021-04-13', '<p>&nbsp;&nbsp;文化和旅游部出台的《国家级文化生态保护区管理办法》（以下简称《办法》）于2019年3月1日起正式施行。《办法》强调设立文化生态保护区，对非遗进行区域性整体保护。目前，我国已批准建设了21个国家级文化生态保护试验区和146个省级文化生态保护区。</p><p>&nbsp;&nbsp;《办法》的出台除了为非遗保护提供至关重要的制度保障，其更深刻的意义在于确立政策导向，进而形成具有引领性的保护理念。文化生态保护区建设为非遗保护提供了很好的实践思路，非遗不仅存在于符合设立保护区条件的区域，在广大村镇和城市中也有广泛分布。如何将散布在保护区之外的众多非遗资源纳入文化生态保护范围，需要进一步进行政策解读和理论阐释。只有将文化生态保护的概念和理念研究透，深入渗透到非遗保护的各个领域和环节，用于指导非遗保护工作，才能达到“泰山遍雨，河润千里”的效果。</p><p><br></p><p>&nbsp;&nbsp;首先，文化生态保护理念有利于将非遗保护与生态建设更紧密地联系起来，使非遗保护工作得到来自生态建设方面的支持。在生态建设已成为社会共识的今天，强调非遗资源与生态环境之间的关联，不失为一种有效的推进策略。要使社会公众意识到，生态保护不仅是自然生态，也包括文化生态，不仅要青山绿水，也要人文气息。达到人与自然的和谐，才是生态保护最理想的状态。实际上，除了经济贫困，文化贫困也是造成偏远地区生态破坏的重要原因。通过文化生态保护，发掘地方非遗资源，并融入社会生活，可以使文化更为醇厚。同时，文化生态与自然生态一样，都是体现地方魅力的名片，因此通过发展旅游产业使文化生态保护工作获得充分回报，可以为地方发展带来可持续的“造血”机制。</p><p><br></p><p>&nbsp;&nbsp;其次，将文化生态保护理念融入非遗保护工作，可以为非遗保护找到更合适的政策支点以及落地途径。文化生态理念对非遗保护的重要意义越来越受关注，更为系统的逻辑阐释以及真正可落地的顶层设计需要加强。更新并完善文化生态保护的精神内核，可以从已付诸实施的政策中寻**作空间，从而为非遗保护开辟新路径。</p>', '如光不息', '显示', '普通', '1');

-- ----------------------------
-- Table structure for replies
-- ----------------------------
DROP TABLE IF EXISTS `replies`;
CREATE TABLE `replies` (
  `reply_id` int(11) NOT NULL AUTO_INCREMENT COMMENT '回复ID',
  `user` char(30) DEFAULT NULL COMMENT '回复者',
  `byReply_user` char(30) DEFAULT NULL COMMENT '被回复者',
  `date` char(32) DEFAULT NULL COMMENT '回复日期',
  `content` varchar(120) DEFAULT NULL COMMENT '回复内容',
  `status` char(6) DEFAULT NULL COMMENT '展示状态',
  `byReply_id` char(11) DEFAULT NULL COMMENT '被回复的评论ID',
  PRIMARY KEY (`reply_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

