-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` char(20) DEFAULT NULL COMMENT '用户名',
  `password` varchar(100) DEFAULT NULL COMMENT '密码',
  `email` varchar(25) DEFAULT NULL COMMENT '邮箱',
  `phone` char(11) DEFAULT NULL COMMENT '手机',
  `sex` char(4) DEFAULT NULL COMMENT '性别',
  `header` varchar(100) DEFAULT NULL COMMENT '头像',
  `lastLogin` char(32) DEFAULT NULL COMMENT '最近登录',
  `regDate` char(32) DEFAULT NULL COMMENT '注册时间',
  `role` char(16) DEFAULT NULL COMMENT '角色',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8;

